#include <stdio.h>
#include <string.h>

#define MAX_INPUT_LEN   1023   /* limit enforced by the original program */
#define MAX_OUTPUT_LEN  2047   /* size of the static output buffer */

static char main_out[MAX_OUTPUT_LEN + 1];   /* +1 for the terminating NUL */

/* Escape a plain string. Returns a pointer to the static buffer. */
static const char *escape_string(const char *src)
{
    size_t out_idx = 0;
    for (size_t i = 0; src[i] != '\0' && out_idx < MAX_OUTPUT_LEN; ++i) {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '\\':
                if (out_idx + 2 > MAX_OUTPUT_LEN) break;
                main_out[out_idx++] = '\\';
                main_out[out_idx++] = '\\';
                break;
            case '"':
                if (out_idx + 2 > MAX_OUTPUT_LEN) break;
                main_out[out_idx++] = '\\';
                main_out[out_idx++] = '"';
                break;
            case '\n':
                if (out_idx + 2 > MAX_OUTPUT_LEN) break;
                main_out[out_idx++] = '\\';
                main_out[out_idx++] = 'n';
                break;
            case '\t':
                if (out_idx + 2 > MAX_OUTPUT_LEN) break;
                main_out[out_idx++] = '\\';
                main_out[out_idx++] = 't';
                break;
            default:
                main_out[out_idx++] = (char)c;
                break;
        }
    }
    main_out[out_idx] = '\0';
    return main_out;
}

/* Un‑escape an escaped string. Returns a pointer to the static buffer. */
static const char *unescape_string(const char *src)
{
    size_t out_idx = 0;
    for (size_t i = 0; src[i] != '\0' && out_idx < MAX_OUTPUT_LEN; ++i) {
        if (src[i] == '\\' && src[i + 1] != '\0') {
            char nxt = src[i + 1];
            switch (nxt) {
                case 'n':
                    main_out[out_idx++] = '\n';
                    ++i;
                    break;
                case 't':
                    main_out[out_idx++] = '\t';
                    ++i;
                    break;
                case '\\':
                    main_out[out_idx++] = '\\';
                    ++i;
                    break;
                case '"':
                    main_out[out_idx++] = '"';
                    ++i;
                    break;
                default:
                    /* Unknown escape – copy the character after the backslash */
                    main_out[out_idx++] = nxt;
                    ++i;
                    break;
            }
        } else {
            main_out[out_idx++] = src[i];
        }
    }
    main_out[out_idx] = '\0';
    return main_out;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];
    size_t in_len = strlen(input);

    if (in_len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        puts(escape_string(input));
    } else if (strcmp(mode, "unescape") == 0) {
        puts(unescape_string(input));
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
